package com.trustserve;
import java.util.*;import java.time.*;import java.nio.file.*;import java.security.Principal;
import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.security.web.csrf.CsrfToken;import jakarta.servlet.http.*;
@RestController @RequestMapping("/api") public class Api {
final AccountRepository users;final ProfessionalProfileRepository pros;final HomeServiceRepository services;final ServiceCategoryRepository categories;final BookingRepository bookings;final PaymentRepository payments;final ReviewRepository reviews;final NotificationRepository notifications;final SupportTicketRepository tickets;final AdminAuditLogRepository audit;final ProfessionalVerificationRepository verifications;final BookingStatusHistoryRepository histories;final BCryptPasswordEncoder encoder;final NoticeService notices;
@Value("${trustserve.storage}") String storage;
public Api(AccountRepository a,ProfessionalProfileRepository p,HomeServiceRepository s,ServiceCategoryRepository c,BookingRepository b,PaymentRepository py,ReviewRepository r,NotificationRepository n,SupportTicketRepository t,AdminAuditLogRepository au,ProfessionalVerificationRepository v,BookingStatusHistoryRepository h,BCryptPasswordEncoder e,NoticeService ns){users=a;pros=p;services=s;categories=c;bookings=b;payments=py;reviews=r;notifications=n;tickets=t;audit=au;verifications=v;histories=h;encoder=e;notices=ns;}
String str(Map<String,Object> m,String k){return Objects.toString(m.get(k),"").trim();} long id(Map<String,Object>m,String k){return Long.parseLong(str(m,k));}
void require(boolean b,String message){if(!b)throw new IllegalArgumentException(message);}
Account me(Principal p){if(p==null)throw new org.springframework.security.access.AccessDeniedException("Login required");Account a=users.findById(Long.valueOf(p.getName())).orElseThrow();if(!a.active)throw new org.springframework.security.access.AccessDeniedException("Account suspended");return a;}
void role(Account a,String r){if(!a.role.equals(r))throw new org.springframework.security.access.AccessDeniedException("Not allowed");}
ProfessionalProfile pro(Account a){return pros.findAll().stream().filter(p->p.account.id.equals(a.id)).findFirst().orElseThrow();}
void owner(Account a,Booking b){if(!a.role.equals("ADMIN")&&!b.customer.id.equals(a.id)&&!b.professional.account.id.equals(a.id))throw new org.springframework.security.access.AccessDeniedException("Not allowed");}
void log(Account a,String action){AdminAuditLog l=new AdminAuditLog();l.actor=a.id;l.action=action;audit.save(l);}
void history(Booking b,Account a){BookingStatusHistory h=new BookingStatusHistory();h.booking=b;h.actor=a.id;h.status=b.status;histories.save(h);notices.send(b.customer,"Booking #"+b.id+": "+b.status);notices.send(b.professional.account,"Booking #"+b.id+": "+b.status);}
@GetMapping("/auth/csrf") public Map<String,String> csrf(CsrfToken token){return Map.of("token",token.getToken(),"header",token.getHeaderName());}
@GetMapping("/auth/me") public Account current(Principal p){return me(p);}
@PostMapping("/auth/register") public synchronized Account register(@RequestBody Map<String,Object> m){String email=str(m,"email").toLowerCase(),pass=str(m,"password"),role=str(m,"role");require(email.matches("[^@\\s]+@[^@\\s]+\\.[^@\\s]+"),"Enter a valid email");require(users.findAll().stream().noneMatch(a->a.email.equals(email)),"Email already registered");Rules.password(pass);require(List.of("CUSTOMER","PROFESSIONAL").contains(role),"Invalid role");require(str(m,"name").length()>=2,"Name is required");Account a=new Account();a.email=email;a.name=str(m,"name");a.password=encoder.encode(pass);a.role=role;users.save(a);if(role.equals("PROFESSIONAL")){ProfessionalProfile p=new ProfessionalProfile();p.account=a;pros.save(p);}return a;}
@PostMapping("/auth/login") public Account login(@RequestBody Map<String,Object> m,HttpServletRequest req){Account a=users.findAll().stream().filter(u->u.email.equalsIgnoreCase(str(m,"email"))).findFirst().orElseThrow(()->new IllegalArgumentException("Invalid credentials"));require(a.active&&encoder.matches(str(m,"password"),a.password),"Invalid credentials");req.getSession(true);req.changeSessionId();var ctx=SecurityContextHolder.createEmptyContext();ctx.setAuthentication(new UsernamePasswordAuthenticationToken(a.id.toString(),null,List.of(new SimpleGrantedAuthority("ROLE_"+a.role))));SecurityContextHolder.setContext(ctx);req.getSession().setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,ctx);return a;}
@PostMapping("/auth/logout") public Map<String,String> logout(HttpServletRequest r){if(r.getSession(false)!=null)r.getSession().invalidate();SecurityContextHolder.clearContext();return Map.of("message","Signed out");}
@GetMapping("/categories") public Object categories(){return categories.findAll();}
@GetMapping("/services") public Object services(){return services.findAll().stream().filter(s->s.active).toList();}
@GetMapping("/services/{id}") public Object service(@PathVariable Long id){return services.findById(id).filter(s->s.active).orElseThrow();}
@GetMapping("/professionals") public Object professionals(){return pros.findAll().stream().filter(p->p.account.active).map(p->Map.of("id",p.id,"name",p.account.name,"skills",p.skills,"area",p.area,"experience",p.experience,"verification",p.verification,"available",p.available,"bio",p.bio)).toList();}
@GetMapping("/professionals/{id}/reviews") public Object ratings(@PathVariable Long id){return reviews.findAll().stream().filter(r->r.visible&&r.booking.professional.id.equals(id)).map(r->Map.of("rating",r.rating,"comment",r.comment)).toList();}
@GetMapping("/profile") public Object profile(Principal p){Account a=me(p);return Map.of("user",a,"professional",a.role.equals("PROFESSIONAL")?pro(a):Map.of());}
@PutMapping("/profile") public Object profile(Principal p,@RequestBody Map<String,Object> m){Account a=me(p);require(str(m,"name").length()>=2,"Name required");a.name=str(m,"name");a.phone=str(m,"phone");a.address=str(m,"address");users.save(a);if(a.role.equals("PROFESSIONAL")){ProfessionalProfile pr=pro(a);pr.skills=str(m,"skills");pr.area=str(m,"area");pr.experience=str(m,"experience");pr.bio=str(m,"bio");pr.available=Boolean.parseBoolean(str(m,"available"));pr.verification="Pending Verification";pros.save(pr);}return a;}
@PostMapping("/verification") public Object verification(Principal principal,@RequestParam("file") MultipartFile file)throws Exception{Account a=me(principal);role(a,"PROFESSIONAL");require(file.getSize()>0&&file.getSize()<=2097152,"Use a demo file under 2 MB");byte[] data=file.getBytes();boolean pdf=data.length>4&&new String(data,0,4).equals("%PDF"),png=data.length>8&&data[0]==(byte)137&&data[1]==80&&data[2]==78;require(pdf||png,"Only PDF or PNG demo documents accepted");Path dir=Paths.get(storage).toAbsolutePath();Files.createDirectories(dir);String name=UUID.randomUUID()+(pdf?".pdf":".png");Files.write(dir.resolve(name),data);ProfessionalProfile pr=pro(a);pr.documentName=name;pr.verification="Under Review";pros.save(pr);ProfessionalVerification v=new ProfessionalVerification();v.professional=pr;v.status="Under Review";v.reason="Simulated verification application";verifications.save(v);return Map.of("message","Demo application submitted");}
@GetMapping("/bookings") public Object bookings(Principal p){Account a=me(p);return bookings.findAll().stream().filter(b->a.role.equals("ADMIN")||b.customer.id.equals(a.id)||b.professional.account.id.equals(a.id)).toList();}
@PostMapping("/bookings") public synchronized Booking book(Principal p,@RequestBody Map<String,Object> m){Account a=me(p);role(a,"CUSTOMER");HomeService s=services.findById(id(m,"serviceId")).orElseThrow();ProfessionalProfile pr=pros.findById(id(m,"professionalId")).orElseThrow();require(s.active&&pr.account.active&&pr.available&&pr.verification.equals("Verified"),"Professional unavailable or not verified");require(Arrays.asList(pr.skills.split(",")).stream().anyMatch(x->x.trim().equals(s.category.name)),"Professional does not offer this category");LocalDate d=LocalDate.parse(str(m,"date"));String slot=str(m,"slot");Rules.future(d,slot);require(bookings.findAll().stream().noneMatch(b->b.professional.id.equals(pr.id)&&b.date.equals(d)&&b.slot.equals(slot)&&Rules.blocking(b.status)),"This slot is already booked");require(str(m,"address").length()>=15,"Enter a complete address (at least 15 characters)");require(List.of("Cash on Service","Online Demo").contains(str(m,"method")),"Invalid payment method");require(!str(m,"paymentResult").equals("fail"),"Simulated payment failed. No booking created.");Booking b=new Booking();b.customer=a;b.service=s;b.professional=pr;b.date=d;b.slot=slot;b.address=str(m,"address");b.instructions=str(m,"instructions");b.method=str(m,"method");b.amount=s.price;bookings.save(b);Payment py=new Payment();py.booking=b;py.amount=b.amount;py.method=b.method;py.status=b.method.equals("Online Demo")?"Demo Paid":"Due";py.reference="DEMO-"+UUID.randomUUID();payments.save(py);history(b,a);return b;}
@PostMapping("/bookings/{id}/status") public synchronized Booking status(Principal p,@PathVariable Long id,@RequestBody Map<String,Object> m){Account a=me(p);Booking b=bookings.findById(id).orElseThrow();owner(a,b);String next=str(m,"status");if(a.role.equals("CUSTOMER"))require(next.equals("Cancelled")&&!b.status.equals("In Progress"),"Cannot cancel this booking");if(a.role.equals("PROFESSIONAL")){require(List.of("Accepted","Rejected","In Progress","Completed").contains(next),"Invalid professional action");require(pro(a).verification.equals("Verified"),"Professional is not verified");}Rules.transition(b.status,next);b.status=next;bookings.save(b);Payment py=payments.findAll().stream().filter(x->x.booking.id.equals(id)).findFirst().orElseThrow();if(next.equals("Completed"))py.status=b.method.equals("Online Demo")?"Demo Paid":"Collected (demo)";if(List.of("Cancelled","Rejected").contains(next)&&py.status.equals("Demo Paid")){py.status="Demo Refunded";py.refundStatus="Simulated refund complete";}payments.save(py);history(b,a);return b;}
@GetMapping("/bookings/{id}/history") public Object history(Principal p,@PathVariable Long id){Booking b=bookings.findById(id).orElseThrow();owner(me(p),b);return histories.findAll().stream().filter(h->h.booking.id.equals(id)).toList();}
@GetMapping("/bookings/{id}/invoice") public ResponseEntity<String> invoice(Principal p,@PathVariable Long id){Booking b=bookings.findById(id).orElseThrow();owner(me(p),b);String text="TRUSTSERVE — DEMO INVOICE\nBooking #"+b.id+"\n"+b.service.name+"\n"+b.date+" "+b.slot+"\nINR "+b.amount+"\nMethod: "+b.method+"\nThis is an academic prototype, not a tax invoice.";return ResponseEntity.ok().header("Content-Disposition","attachment; filename=invoice-"+id+".txt").contentType(MediaType.TEXT_PLAIN).body(text);}
@GetMapping("/payments") public Object payments(Principal p){Account a=me(p);return payments.findAll().stream().filter(py->a.role.equals("ADMIN")||py.booking.customer.id.equals(a.id)||py.booking.professional.account.id.equals(a.id)).toList();}
@PostMapping("/reviews") public synchronized Object review(Principal p,@RequestBody Map<String,Object> m){Account a=me(p);Booking b=bookings.findById(id(m,"bookingId")).orElseThrow();require(b.customer.id.equals(a.id)&&b.status.equals("Completed"),"Review only your completed bookings");require(reviews.findAll().stream().noneMatch(r->r.booking.id.equals(b.id)),"Already reviewed");int rating=Integer.parseInt(str(m,"rating"));require(rating>=1&&rating<=5,"Rating must be 1–5");require(str(m,"comment").length()>=5&&str(m,"comment").length()<=1500,"Comment must be 5–1500 characters");Review r=new Review();r.booking=b;r.rating=rating;r.comment=str(m,"comment");return reviews.save(r);}
@GetMapping("/notifications") public Object notifications(Principal p){Account a=me(p);return notifications.findAll().stream().filter(n->n.recipient.id.equals(a.id)).toList();}
@GetMapping("/support") public Object support(Principal p){Account a=me(p);return tickets.findAll().stream().filter(t->a.role.equals("ADMIN")||t.customer.id.equals(a.id)).toList();}
@PostMapping("/support") public Object support(Principal p,@RequestBody Map<String,Object> m){require(str(m,"message").length()>=10,"Describe the issue in at least 10 characters");SupportTicket t=new SupportTicket();t.customer=me(p);t.subject=str(m,"subject");t.message=str(m,"message");return tickets.save(t);}
@GetMapping("/admin/data") public Object admin(Principal p){role(me(p),"ADMIN");return Map.of("users",users.findAll(),"professionals",pros.findAll(),"services",services.findAll(),"bookings",bookings.findAll(),"reviews",reviews.findAll(),"audit",audit.findAll(),"tickets",tickets.findAll(),"payments",payments.findAll());}
@PostMapping("/admin/verification/{id}") public Object verify(Principal p,@PathVariable Long id,@RequestBody Map<String,Object> m){Account a=me(p);role(a,"ADMIN");String status=str(m,"status");require(List.of("Verified","Rejected","Suspended","Under Review").contains(status),"Invalid verification status");require(str(m,"reason").length()>=3,"Review reason required");ProfessionalProfile pr=pros.findById(id).orElseThrow();pr.verification=status;pros.save(pr);ProfessionalVerification v=new ProfessionalVerification();v.professional=pr;v.status=status;v.reason=str(m,"reason");verifications.save(v);log(a,"Verification "+id+" "+status+": "+v.reason);notices.send(pr.account,"Verification: "+status);return pr;}
@GetMapping("/admin/document/{id}") public ResponseEntity<byte[]> document(Principal p,@PathVariable Long id)throws Exception{role(me(p),"ADMIN");ProfessionalProfile pr=pros.findById(id).orElseThrow();require(!pr.documentName.isBlank(),"No submitted document");return ResponseEntity.ok().header("Content-Disposition","attachment; filename=demo-document"+(pr.documentName.endsWith(".pdf")?".pdf":".png")).contentType(MediaType.APPLICATION_OCTET_STREAM).body(Files.readAllBytes(Paths.get(storage).resolve(pr.documentName)));}
@PostMapping("/admin/users/{id}") public Object user(Principal p,@PathVariable Long id,@RequestBody Map<String,Object> m){Account a=me(p);role(a,"ADMIN");Account u=users.findById(id).orElseThrow();require(!u.role.equals("ADMIN"),"Admin accounts cannot be suspended here");u.active=Boolean.parseBoolean(str(m,"active"));users.save(u);log(a,"User "+id+" active="+u.active);return u;}
@PostMapping("/admin/services") public Object saveService(Principal p,@RequestBody Map<String,Object> m){Account a=me(p);role(a,"ADMIN");HomeService s=m.get("id")==null?new HomeService():services.findById(id(m,"id")).orElseThrow();s.name=str(m,"name");s.description=str(m,"description");s.price=Integer.parseInt(str(m,"price"));s.duration=Integer.parseInt(str(m,"duration"));require(s.price>0&&s.duration>0&&!s.name.isBlank(),"Name, positive price and duration required");s.category=categories.findById(id(m,"categoryId")).orElseThrow();s.image="/images/home.jpg";s.active=!str(m,"active").equals("false");services.save(s);log(a,"Saved service "+s.id);return s;}
@PostMapping("/admin/categories") public Object category(Principal p,@RequestBody Map<String,Object> m){Account a=me(p);role(a,"ADMIN");String n=str(m,"name");require(!n.isBlank(),"Name required");ServiceCategory c=new ServiceCategory();c.name=n;categories.save(c);log(a,"Created category "+n);return c;}
@PostMapping("/admin/reviews/{id}") public Object moderate(Principal p,@PathVariable Long id,@RequestBody Map<String,Object> m){Account a=me(p);role(a,"ADMIN");require(str(m,"reason").length()>=3,"Reason required");Review r=reviews.findById(id).orElseThrow();r.visible=Boolean.parseBoolean(str(m,"visible"));r.moderationReason=str(m,"reason");reviews.save(r);log(a,"Review "+id+": "+r.moderationReason);return r;}
@PostMapping("/admin/support/{id}") public Object respond(Principal p,@PathVariable Long id,@RequestBody Map<String,Object> m){Account a=me(p);role(a,"ADMIN");SupportTicket t=tickets.findById(id).orElseThrow();require(List.of("Open","In Review","Resolved","Closed").contains(str(m,"status")),"Invalid status");t.status=str(m,"status");t.response=str(m,"response");tickets.save(t);log(a,"Support "+id+" "+t.status);notices.send(t.customer,"Support #"+id+": "+t.status);return t;}
@ExceptionHandler(org.springframework.security.access.AccessDeniedException.class) @ResponseStatus(HttpStatus.FORBIDDEN) public Object forbidden(Exception e){return Map.of("message","Access denied");}
@ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class,org.springframework.dao.DataIntegrityViolationException.class,java.time.format.DateTimeParseException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) public Object bad(Exception e){return Map.of("message",e instanceof IllegalArgumentException?Objects.toString(e.getMessage(),"Invalid request"):"Record unavailable or conflicts with existing data");}
}
